"""Stub jobs and courses across every remaining NSQF sector.

Sibling of seed_marketplace.py, kept separate on purpose: this file's skill references
resolve by Skill.slug directly (the same lookup resolve_standards() uses), never through
LEGACY_SKILL_MAP, and it touches none of the three sectors seed_marketplace.py already covers
(healthcare, retail, logistics) or any slug the golden set references.


Every job/course here is tagged to one real, current QualificationPack in its sector --
its title is a template applied to that QP's real job_role, and its required/taught
standards are that QP's own QpSkill rows (source='nsqf'), picked and counted (2-5 per
sector, drawn from eligible sectors only) by a single reproducible random draw --
seed="sector-expansion-tenants-2026-09-29" -- recorded here, not re-rolled on every run.
Sectors with no current QualificationPack carrying at least 3 real standards
(education-training-and-research, strategic-manufacturing) are skipped rather than faked.

    make seed
"""

import asyncio
import sys
import uuid

# Sibling import, same mechanism seed_marketplace.py itself uses for legacy_skill_map --
# scripts/ is not an installed package, but Python puts a script's own directory on
# sys.path.
from seed_marketplace import _now, _owner_for, _translate  # noqa: E402
from sqlalchemy import delete, select

from api.core.database import dispose_engine, get_sessionmaker
from api.modules.geography import resolve_location
from api.modules.identity.models import Tenant
from api.modules.marketplace.models import Course, CourseSkill, Job, JobSkill
from api.modules.skills.models import Skill

