async def seed() -> dict[str, int]:
    stats = {
        "tenants": 0,
        "owners": 0,
        "jobs": 0,
        "courses": 0,
        "job_skills": 0,
        "course_skills": 0,
    }

    async with get_sessionmaker()() as db:
        referenced = {sl for j in JOBS for sl, _, _ in j[14]} | {
            sl for c in COURSES for sl, _ in c[11]
        }
        found = dict(
            (
                await db.execute(
                    select(Skill.slug, Skill.id).where(
                        Skill.slug.in_(referenced), Skill.source == "nsqf"
                    )
                )
            ).all()
        )
        missing = sorted(referenced - found.keys())
        if missing:
            print(f"Unknown or non-nsqf skill slugs: {', '.join(missing)}", file=sys.stderr)
            raise SystemExit(1)

        tenants: dict[str, Tenant] = {}
        for slug, name, ttype, city, owner_email in TENANTS:
            t = await db.scalar(select(Tenant).where(Tenant.slug == slug))
            if t is None:
                t = Tenant(slug=slug)
                db.add(t)
                stats["tenants"] += 1
            t.name, t.tenant_type, t.city = name, ttype, city
            await db.flush()
            if await _owner_for(db, t, owner_email):
                stats["owners"] += 1
            tenants[slug] = t

        for (
            slug,
            tslug,
            t_en,
            t_hi,
            d_en,
            d_hi,
            state,
            district,
            etype,
            emin,
            emax,
            smin,
            smax,
            nsqf,
            skill_rows,
        ) in JOBS:
            job = await db.scalar(select(Job).where(Job.slug == slug))
            if job is None:
                job = Job(slug=slug)
                db.add(job)
                stats["jobs"] += 1
            job.tenant_id = tenants[tslug].id
            job.title, job.description = t_en, d_en
            await _translate(db, "job", job, {"title": t_hi, "description": d_hi})
            job.location_state, job.location_district = state, district
            located = await resolve_location(db, state, district)
            job.state_id, job.district_id = located.state_id, located.district_id
            job.employment_type = etype
            job.experience_min_years, job.experience_max_years = emin, emax
            job.salary_min_inr, job.salary_max_inr = smin, smax
            job.nsqf_level_min = nsqf
            job.status = "published"
            job.alerted_at = job.alerted_at or _now()
            await db.flush()

            await db.execute(delete(JobSkill).where(JobSkill.job_id == job.id))
            merged: dict[uuid.UUID, tuple[int, bool]] = {}
            for sslug, importance, mandatory in skill_rows:
                sid = found[sslug]
                prev_importance, prev_mandatory = merged.get(sid, (0, False))
                merged[sid] = (max(importance, prev_importance), mandatory or prev_mandatory)
            for sid, (importance, mandatory) in merged.items():
                db.add(
                    JobSkill(
                        job_id=job.id, skill_id=sid, importance=importance, is_mandatory=mandatory
                    )
                )
                stats["job_skills"] += 1

        for (
            slug,
            tslug,
            t_en,
            t_hi,
            d_en,
            d_hi,
            mode,
            lang,
            hours,
            fee,
            nsqf,
            skill_rows,
        ) in COURSES:
            course = await db.scalar(select(Course).where(Course.slug == slug))
            if course is None:
                course = Course(slug=slug)
                db.add(course)
                stats["courses"] += 1
            course.tenant_id = tenants[tslug].id
            course.title, course.description = t_en, d_en
            await _translate(db, "course", course, {"title": t_hi, "description": d_hi})
            course.mode, course.language = mode, lang
            course.duration_hours, course.fee_inr = hours, fee
            course.nsqf_level = nsqf
            course.status = "published"
            await db.flush()

            await db.execute(delete(CourseSkill).where(CourseSkill.course_id == course.id))
            taught: dict[uuid.UUID, float | None] = {}
            for sslug, level_taught in skill_rows:
                sid = found[sslug]
                prev = taught.get(sid)
                taught[sid] = level_taught if prev is None else max(prev, level_taught)
            for sid, level_taught in taught.items():
                db.add(CourseSkill(course_id=course.id, skill_id=sid, level_taught=level_taught))
                stats["course_skills"] += 1

        await db.commit()

    await dispose_engine()
    return stats


async def main() -> None:
    stats = await seed()
    print(
        "tenants created: {tenants}  owners created: {owners}  "
        "jobs: {jobs}  courses: {courses}  "
        "job_skills: {job_skills}  course_skills: {course_skills}".format(**stats)
    )


if __name__ == "__main__":
    asyncio.run(main())
